// === Tab: mySketch ===
let tileCols;
let cw, tileSize, cols, rows;
let gridOffsetX, gridOffsetY, tileGrid;
let colorA = 255, colorB = 0;

function setup() {
  cw = max(windowWidth, windowHeight);
  createCanvas(cw, cw);
  randomSeed(floor(random(1e9)));
  tileCols = floor(random(10, 30));
  tileSize = max(24, floor(width / tileCols));
  cols = floor(width / tileSize);
  rows = floor(height / tileSize);

  gridOffsetX = round((width - cols * tileSize) / 2);
  gridOffsetY = round((height - rows * tileSize) / 2);

  tileGrid = [];
  for (let row = 0; row < rows; row++) {
    tileGrid[row] = [];
    for (let col = 0; col < cols; col++) {
      const even = (col + row) % 2 === 0;
      tileGrid[row][col] = even ? random([0, 3]) : random([1, 2]);
    }
  }
  noStroke();
}

function draw() {
  background(colorA);
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const x = gridOffsetX + col * tileSize;
      const y = gridOffsetY + row * tileSize;
      drawTruchetTile(tileGrid[row][col], x, y, tileSize);
    }
  }
}

function drawTruchetTile(variant, x, y, size) {
  push();
  let distanceToMouse = dist(x, y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  let roundness = map(distanceToMouse, size, max(10 * size, cw / 3), size/2, 0, true);
  translate(x, y);
  clip(() => rect(0, 0, size, size));

  rectMode(CENTER);
  noStroke();
  let fillA = variant === 0 || variant === 1 ? colorA : colorB;
  let fillB = variant === 0 || variant === 1 ? colorB : colorA;
  fill(fillA);
  rect(size/2, size/2, size, size);
  fill(fillB);
  if (variant === 0 || variant === 2) {
    rect(0, 0, size, size, roundness);
    rect(size, size, size, size, roundness);
  } else {
    rect(size, 0, size, size, roundness);
    rect(0, size, size, size, roundness);
  }
  pop();
}
